document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("raised-bed-form"),n=document.getElementById("raised-bed-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("bed-length").value),s=parseFloat(document.getElementById("bed-width").value),i=parseFloat(document.getElementById("bed-depth").value),o=parseFloat(document.getElementById("bed-quantity").value),a=parseFloat(document.getElementById("soil-mix").value),p=document.getElementById("purchase-method").value;if(t<=0||s<=0||i<=0||o<=0)return n.textContent="Please enter valid measurements.",void 0;const l=t*s*(i/12),d=l/27,r=l*o,c=d*o,u=1.15*c;let m,$,g,h;if("bulk"===p)m=Math.ceil(2*u)/2,$="cubic yards",g=m*a,m<3&&(g+=75),h=Math.ceil(r/2);else{h=Math.ceil(1.15*r/2),m=h,$="bags (2 cu ft each)";g=1.15*r/27*(2.5*a)}const v=t*s*o*(1/12)/27,b=v*a*.8,f=2*(t+s)*o,F=Math.ceil(f/8),y=15*F,B=20*o,x=y+B,I={35:{compost:30,topsoil:60,amendments:10},45:{compost:40,topsoil:40,amendments:20},55:{compost:50,topsoil:30,amendments:20},65:{compost:60,topsoil:20,amendments:20},30:{compost:20,topsoil:70,amendments:10}}[a];n.innerHTML=`\n        <div class="result-section">\n          <h4>Raised Bed Specifications:</h4>\n          <p>Bed size: ${t}' × ${s}' × ${i}"</p>\n          <p>Number of beds: ${o}</p>\n          <p>Volume per bed: ${l.toFixed(2)} cu ft (${d.toFixed(2)} cu yds)</p>\n          <p><strong>Total volume needed: ${c.toFixed(2)} cubic yards</strong></p>\n        </div>\n        \n        <div class="result-soil">\n          <h4>Soil Requirements:</h4>\n          <p>Base requirement: ${c.toFixed(2)} cubic yards</p>\n          <p>With settlement factor: ${u.toFixed(2)} cubic yards</p>\n          <p><strong>Order: ${m} ${$}</strong></p>\n          <p><strong>Total cost: $${g.toFixed(0)}</strong></p>\n          ${"bulk"===p&&m<3?"<p><em>Includes $75 delivery fee for small orders</em></p>":""}\n        </div>\n        \n        <div class="result-composition">\n          <h4>Soil Mix Composition:</h4>\n          <p>Compost/Organic matter: ${I.compost}%</p>\n          <p>Topsoil/Base material: ${I.topsoil}%</p>\n          <p>Amendments (perlite, sand): ${I.amendments}%</p>\n          <p>pH level: 6.0-7.0 (ideal for vegetables)</p>\n        </div>\n        \n        <div class="result-comparison">\n          <h4>Cost Comparison:</h4>\n          <p>Bulk delivery: $${g.toFixed(0)}</p>\n          ${"bulk"===p?`<p>Bagged equivalent: $${(4*h).toFixed(0)} (${h} bags @ $4 each)</p>\n             <p>💰 Bulk saves: $${(4*h-g).toFixed(0)}</p>`:`<p>Bulk alternative: $${(u*a+(u<3?75:0)).toFixed(0)}</p>\n             <p>💰 ${"bags"===p?"Bulk saves":"Bagged costs"}: $${Math.abs(g-(u*a+(u<3?75:0))).toFixed(0)} more</p>`}\n        </div>\n        \n        <div class="result-construction">\n          <h4>Bed Construction (Optional):</h4>\n          <p>Lumber needed: ${F} pieces (8ft cedar boards)</p>\n          <p>Total perimeter: ${f} linear feet</p>\n          <p>Lumber cost: $${y.toFixed(0)}</p>\n          <p>Hardware cost: $${B.toFixed(0)}</p>\n          <p><strong>Construction materials: $${x.toFixed(0)}</strong></p>\n        </div>\n        \n        <div class="result-maintenance">\n          <h4>Annual Maintenance:</h4>\n          <p>Yearly top-up: ${v.toFixed(2)} cubic yards</p>\n          <p>Annual compost cost: $${b.toFixed(0)}</p>\n          <p>Maintenance: Add 1-2" compost each spring</p>\n          <p>Soil testing: Every 2-3 years ($15-25)</p>\n        </div>\n        \n        <div class="result-delivery">\n          <h4>Delivery & Installation:</h4>\n          ${"bulk"===p?`\n          <p>Delivery truck access: 12+ feet wide needed</p>\n          <p>Wheelbarrow trips: ${Math.ceil(27*u/4)} (4 cu ft per trip)</p>\n          <p>Installation time: ${(2*u).toFixed(1)} hours</p>\n          `:`\n          <p>Bag transport: ${h} bags @ 40 lbs each</p>\n          <p>Total weight: ${(40*h).toLocaleString()} lbs</p>\n          <p>Vehicle trips: ${Math.ceil(h/20)} (20 bags per trip)</p>\n          `}\n        </div>\n        \n        <div class="result-planting">\n          <h4>Planting Guidelines:</h4>\n          <p>Planting area: ${(t*s*o).toFixed(0)} sq ft total</p>\n          ${i>=12?"<p>✅ Suitable for all vegetables</p>":"<p>⚠️ Limited to shallow-root crops</p>"}\n          <p>Plant spacing: Follow seed packet recommendations</p>\n          <p>First planting: Wait 1-2 weeks after filling</p>\n        </div>\n        \n        <div class="result-benefits">\n          <h4>Raised Bed Benefits:</h4>\n          <p>🌱 Better drainage and soil aeration</p>\n          <p>🔥 Faster soil warming in spring</p>\n          <p>🚫 Reduced soil compaction</p>\n          <p>🌿 Easier weed control</p>\n          <p>♿ Accessible gardening height</p>\n        </div>\n        \n        <div class="result-tips">\n          <h4>Installation Tips:</h4>\n          <p>📍 Choose sunny location (6-8 hours daily)</p>\n          <p>💧 Install near water source</p>\n          <p>📏 Level the bed foundation</p>\n          <p>🛡️ Consider landscape fabric liner</p>\n          <p>⏰ Fill beds just before planting season</p>\n        </div>\n      `})});